# And fill empty blocks with 5?

test_input = input_grid
results = []

for row in range(9):
    row_output = []
    for col in range(9):
        start_row = row * 3
        start_col = col * 3
        block_values = [test_input[start_row+dr][start_col+dc] for dr in range(3) for dc in range(3)]

        color_counts = Counter(block_values)
        max_count = max(color_counts.values())

        # A block is "dominated" by a color if that color is > 50% of 9 cells
        if max_count > 4:  # > 50%
            for c, cnt in color_counts.items():
                if cnt == max_count and c not in [0]:
                    row_output.append(c)
                    break
            else:
                # No single color > 4, check for dominance by non-bg only
                non_bg = {c: cnt for c, cnt in color_counts.items() if c not in [0, 5]}
                if non_bg:
                    max_count_nb = max(non_bg.values())
                    if max_count_nb > len(non_bg) // 2:  # > half of non-bg cells have same color
                        for c, cnt in non_bg.items():
                            if cnt == max_count_nb:
                                row_output.append(c)
                                break
                        else:
                            row_output.append(5)
                else:
                    row_output.append(5)
        else:
            # Not dominated, check non-bg
            non_bg = {c: cnt for c, cnt in color_counts.items() if c not in [0, 5]}
            if non_bg:
                max_count_nb = max(non_bg.values())
                winners = [c for c, cnt in non_bg.items() if cnt == max_count_nb]
                row_output.append(min(winners))
            else:
                row_output.append(5)
    results.append(row_output)

print("9x9 output:")
